bool on = false;

void setup() {
  pinMode(9, OUTPUT);
  digitalWrite(9, HIGH); // fail-safe: fan ON at boot
}

void loop() {
  int raw = analogRead(A2);
  // 10 mV/degC, 5 V / 1023 counts => 0.0048876 V/count => 0.48876 degC/count
  float c = raw * (5.0 / 1023.0) * 100.0; // 10 mV/degC => 100 degC per volt

  bool failSafe = (raw <= 2) || (raw >= 1020) || (c > 100.0) || (c < 0.0);

  if (failSafe) {
    on = true;
  } else if (c >= 28.0) {
    on = true;
  } else if (c <= 24.0) {
    on = false;
  }
  // else: keep previous state (hysteresis band 24..28)

  digitalWrite(9, on ? HIGH : LOW);
  delay(50);
}
